import unittest

class LogEntry:
    def __init__(self, log_line):
        parts = log_line.strip().split(',')
        if len(parts) >= 3:
            self.timestamp = parts[0]
            self.level = parts[1]
            self.message = parts[2]
        else:
            self.level = "UNKNOWN"

def get_errors(file_content):
    errors = []
    lines = file_content.strip().split('\n')
    for line in lines:
        if not line.strip(): continue
        entry = LogEntry(line)
        if entry.level == "ERROR":
            errors.append(entry)
    return errors

class TestFilter(unittest.TestCase):
    def test_filter(self):
        data = "2026-01-01,INFO,Start\n2026-01-01,ERROR,Crash\n2026-01-01,DEBUG,Test"
        results = get_errors(data)
        self.assertEqual(len(results), 1)
        self.assertEqual(results[0].message, "Crash")

if __name__ == '__main__':
    unittest.main()
